1	import { forbidden, unauthorized } from "../errors.js";
2	import type { ActorMembership } from "../http/types.js";
3	
4	/**
5	 * Minimal structural interface satisfied by both Express Request (post-actorMiddleware)
6	 * and RequestCtx, allowing authz helpers to work in both Express handlers and
7	 * transport-agnostic Handler functions.
8	 */
9	export interface AuthzReq {
10	  actor:
11	    | {
12	        type: string;
13	        source?: string;
14	        isInstanceAdmin?: boolean;
15	        companyIds?: string[];
16	        memberships?: Array<{ companyId: string; membershipRole?: string | null; status?: string }>;
17	        userId?: string;
18	        agentId?: string;
19	        companyId?: string;
20	        runId?: string;
21	      }
22	    | null
23	    | undefined;
24	  method: string;
25	}
26	
27	function isAuthenticated(req: AuthzReq): boolean {
28	  return !!req.actor && req.actor.type !== "none";
29	}
30	
31	export function assertAuthenticated(req: AuthzReq): void {
32	  if (!isAuthenticated(req)) throw unauthorized();
33	}
34	
35	export function assertBoard(req: AuthzReq): void {
36	  if (!req.actor || req.actor.type !== "board") throw forbidden("Board access required");
37	}
38	
39	export function hasBoardOrgAccess(req: AuthzReq): boolean {
40	  if (!req.actor || req.actor.type !== "board") return false;
41	  if (req.actor.source === "local_implicit" || req.actor.isInstanceAdmin) return true;
42	  return Array.isArray(req.actor.companyIds) && req.actor.companyIds.length > 0;
43	}
44	
45	export function assertBoardOrgAccess(req: AuthzReq): void {
46	  assertBoard(req);
47	  if (hasBoardOrgAccess(req)) return;
48	  throw forbidden("Company membership or instance admin access required");
49	}
50	
51	export function assertInstanceAdmin(req: AuthzReq): void {
52	  assertBoard(req);
53	  if (req.actor?.source === "local_implicit" || req.actor?.isInstanceAdmin) return;
54	  throw forbidden("Instance admin access required");
55	}
56	
57	export function assertCompanyAccess(req: AuthzReq, companyId: string): void {
58	  assertAuthenticated(req);
59	  if (!req.actor) return;
60	
61	  if (req.actor.type === "agent" && req.actor.companyId !== companyId) {
62	    throw forbidden("Agent key cannot access another company");
63	  }
64	
65	  if (req.actor.type === "board" && req.actor.source !== "local_implicit") {
66	    const allowedCompanies = req.actor.companyIds ?? [];
67	    if (!allowedCompanies.includes(companyId)) {
68	      throw forbidden("User does not have access to this company");
69	    }
70	    const method = typeof req.method === "string" ? req.method.toUpperCase() : "GET";
71	    const isSafeMethod = ["GET", "HEAD", "OPTIONS"].includes(method);
72	    if (!isSafeMethod && !req.actor.isInstanceAdmin && Array.isArray(req.actor.memberships)) {
73	      const membership = req.actor.memberships.find((item) => item.companyId === companyId);
74	      if (!membership || membership.status !== "active") {
75	        throw forbidden("User does not have active company access");
76	      }
77	      if ((membership as ActorMembership).membershipRole === "viewer") {
78	        throw forbidden("Viewer access is read-only");
79	      }
80	    }
81	  }
82	}
83	
84	export function getActorInfo(req: AuthzReq) {
85	  assertAuthenticated(req);
86	  if (!req.actor) throw unauthorized();
87	
88	  if (req.actor.type === "agent") {
89	    return {
90	      actorType: "agent" as const,
91	      actorId: req.actor.agentId ?? "unknown-agent",
92	      agentId: req.actor.agentId ?? null,
93	      runId: req.actor.runId ?? null,
94	    };
95	  }
96	
97	  return {
98	    actorType: "user" as const,
99	    actorId: req.actor.userId ?? "board",
100	    agentId: null,
101	    runId: req.actor.runId ?? null,
102	  };
103	}
